-- =======================================================
-- 850導入 / DB install ─ 成就圖鑑收集設定與獎勵
-- 涵蓋：w_achievement_codex (收集要求)
--       w_achievement_reward (完成屬性獎勵)
-- =======================================================
SET NAMES utf8mb4;

-- 1. 成就圖鑑收集設定表
DROP TABLE IF EXISTS `w_achievement_codex`;
CREATE TABLE `w_achievement_codex` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `npcid` int(11) NOT NULL DEFAULT 93062,
  `action` varchar(50) NOT NULL,
  `note` varchar(100) NOT NULL DEFAULT '',
  `check_level` int(11) NOT NULL DEFAULT 0,
  `check_class` int(11) NOT NULL DEFAULT 0,
  `materials` varchar(255) NOT NULL COMMENT '需求材料道具ID清單',
  `materials_note` varchar(255) NOT NULL DEFAULT '' COMMENT '材料中文名稱說明',
  `materials_count` varchar(255) NOT NULL COMMENT '材料數量清單',
  `materials_enchants` varchar(255) NOT NULL COMMENT '材料強化值要求清單',
  `success_html` varchar(255) NOT NULL DEFAULT '',
  `fail_html` varchar(255) NOT NULL DEFAULT '',
  `all_message` varchar(255) NOT NULL DEFAULT '',
  `quest_id` int(11) NOT NULL COMMENT '完成綁定之任務編號',
  `ability_desc` varchar(100) NOT NULL DEFAULT '' COMMENT '完成獲得能力摘要',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_quest` (`quest_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='成就圖鑑收集要求設定';

-- 2. 成就圖鑑收集完成屬性獎勵表
DROP TABLE IF EXISTS `w_achievement_reward`;
CREATE TABLE `w_achievement_reward` (
  `quest_id` int(11) NOT NULL COMMENT '對應成就任務ID',
  `note1` varchar(100) NOT NULL DEFAULT '' COMMENT '成就名稱',
  `note` varchar(100) NOT NULL DEFAULT '' COMMENT '屬性摘要說明',
  `attack` smallint(6) NOT NULL DEFAULT 0,
  `bow_attack` smallint(6) NOT NULL DEFAULT 0,
  `hit` smallint(6) NOT NULL DEFAULT 0,
  `bow_hit` smallint(6) NOT NULL DEFAULT 0,
  `sp` smallint(6) NOT NULL DEFAULT 0,
  `str` smallint(6) NOT NULL DEFAULT 0,
  `dex` smallint(6) NOT NULL DEFAULT 0,
  `intel` smallint(6) NOT NULL DEFAULT 0,
  `con` smallint(6) NOT NULL DEFAULT 0,
  `cha` smallint(6) NOT NULL DEFAULT 0,
  `wis` smallint(6) NOT NULL DEFAULT 0,
  `hp` int(11) NOT NULL DEFAULT 0,
  `mp` int(11) NOT NULL DEFAULT 0,
  `mr` smallint(6) NOT NULL DEFAULT 0,
  `reduction_dmg` smallint(6) NOT NULL DEFAULT 0,
  `hpr` smallint(6) NOT NULL DEFAULT 0,
  `mpr` smallint(6) NOT NULL DEFAULT 0,
  `hp_potion` smallint(6) NOT NULL DEFAULT 0,
  `exp` double NOT NULL DEFAULT 0.0,
  `ac` smallint(6) NOT NULL DEFAULT 0,
  `weight` smallint(6) NOT NULL DEFAULT 0,
  `regist_stun` smallint(6) NOT NULL DEFAULT 0,
  `regist_stone` smallint(6) NOT NULL DEFAULT 0,
  `regist_sleep` smallint(6) NOT NULL DEFAULT 0,
  `regist_freeze` smallint(6) NOT NULL DEFAULT 0,
  `regist_sustain` smallint(6) NOT NULL DEFAULT 0,
  `regist_blind` smallint(6) NOT NULL DEFAULT 0,
  `pvp_dmg` smallint(6) NOT NULL DEFAULT 0,
  `pvp_hit` smallint(6) NOT NULL DEFAULT 0,
  `pvp_bow_dmg` smallint(6) NOT NULL DEFAULT 0,
  `pvp_bow_hit` smallint(6) NOT NULL DEFAULT 0,
  `pvp_dmg_r` smallint(6) NOT NULL DEFAULT 0,
  `pvp_magic_r` smallint(6) NOT NULL DEFAULT 0,
  `ran_pvp_dmg_b` int(11) NOT NULL DEFAULT 0,
  `pvp_dmg_b` varchar(45) NOT NULL DEFAULT '0',
  `ran_pvp_magic_b` int(11) NOT NULL DEFAULT 0,
  `pvp_magic_b` varchar(45) NOT NULL DEFAULT '0',
  PRIMARY KEY (`quest_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='成就圖鑑收集獎勵屬性';
